// Pull current price + full 24h chart, compute real stats, and decide crash severity.
const currentPrice = $('Fetch Current Asset Price').item.json[$('Set Asset Parameters').item.json.Asset].usd;
const chart = $input.first().json;
const prices = chart.prices;

if (!prices || prices.length === 0) {
  throw new Error('No price data returned from CoinGecko market_chart endpoint');
}

const priceValues = prices.map(p => p[1]);
const periodHigh = Math.max(...priceValues);
const periodLow = Math.min(...priceValues);
const price24hAgo = priceValues[0];

const percentChange24h = ((currentPrice - price24hAgo) / price24hAgo) * 100;
const percentDropFromHigh = ((periodHigh - currentPrice) / periodHigh) * 100;

const crashThreshold = parseFloat($('Set Asset Parameters').item.json.Crash_threshold);
const percentDropThreshold = parseFloat($('Set Asset Parameters').item.json.Percent_drop_threshold);

// Crash if: price fell below the absolute floor, OR it dropped more than X% off its 24h high
const isCrash = (currentPrice < crashThreshold) || (percentDropFromHigh >= percentDropThreshold);

// Normal days: downsample to ~24 points so we don't burn tokens sending 288 raw entries to the LLM.
// Crash days: send the FULL raw series so the LLM can actually see the shape of the move.
const toPoint = ([ts, price]) => ({
  time: new Date(ts).toISOString(),
  price: Math.round(price * 100) / 100
});

let llmPriceData;
if (isCrash) {
  llmPriceData = prices.map(toPoint);
} else {
  const sampleEvery = Math.max(1, Math.floor(prices.length / 24));
  llmPriceData = prices.filter((_, idx) => idx % sampleEvery === 0).map(toPoint);
}

return [{
  json: {
    asset: $('Set Asset Parameters').item.json.Asset,
    ticker: $('Set Asset Parameters').item.json.Ticker,
    current_price: Math.round(currentPrice * 100) / 100,
    period_high_24h: Math.round(periodHigh * 100) / 100,
    period_low_24h: Math.round(periodLow * 100) / 100,
    price_24h_ago: Math.round(price24hAgo * 100) / 100,
    percent_change_24h: Math.round(percentChange24h * 100) / 100,
    percent_drop_from_high: Math.round(percentDropFromHigh * 100) / 100,
    crash_threshold: crashThreshold,
    percent_drop_threshold: percentDropThreshold,
    is_crash: isCrash,
    is_full_data: isCrash,
    raw_point_count: prices.length,
    llm_price_data: llmPriceData
  }
}];

