// Grab the top articles + metadata for the LLM and for the Slack message.
const response = $input.first().json;
const items = response.data || [];

// Limit to a maximum of 5 posts, or less if specified in Config
const configLimit = parseInt($('Set Asset Parameters').item.json.News_limit, 10) || 5;
const newsLimit = Math.min(configLimit, 5);

const articles = items.slice(0, newsLimit).map(article => {
  // Extract description and truncate to 200 characters
  let desc = article.description || "No description available.";

  if (desc.length > 200) {
    desc = desc.substring(0, 200) + "...";
  }

  return {
    title: article.title,
    description: desc,
    url: article.url,
    source: article.source || "Unknown",
    published_at: article.published_at,
  };
});

// Format titles and descriptions for the AI prompt
const titlesFormatted = articles
  .map(
    (a, i) =>
      `${i + 1}. ${a.title} (${a.source})\nSummary: ${a.description}`
  )
  .join("\n\n");

return [
  {
    json: {
      articles,
      article_count: articles.length,
      titles_formatted:
        titlesFormatted || "No recent headlines found.",
    },
  },
];
